/**
 * Track telemetry: one measured reference lap per circuit (master-plan 13.2,
 * DECISIONS 2026-10-21 "13.1 Track telemetry"). The files under
 * `data/circuits/telemetry/` are generated by `scripts/build-circuit-telemetry.ts`
 * from OpenF1 and validated by `tests/circuit-telemetry-data.test.ts`.
 */

/**
 * One sample of the lap: `tMs` from lap start, `dM` integer metres, `throttle`
 * 0–100, `x`/`y` inside a 0–1000 box in SVG orientation (y down).
 */
export type TelemetrySample = readonly [
  tMs: number,
  dM: number,
  kmh: number,
  gear: number,
  throttle: number,
  brake: 0 | 1,
  x: number,
  y: number,
];

export interface TelemetrySource {
  provider: 'OpenF1';
  license: 'CC BY-NC-SA 4.0';
  url: 'https://openf1.org';
  year: number;
  round: number;
  raceName: string;
  session: 'Qualifying';
  sessionKey: number;
  meetingKey: number;
  driverNumber: number;
  driverId: string;
  driverCode: string;
  lapNumber: number;
  lapTime: string;
  lapDurationMs: number;
  fetchedAt: string;
}

export interface LapMetrics {
  lapLengthM: number;
  topSpeedKmh: number;
  minSpeedKmh: number;
  fullThrottlePct: number;
  brakingPct: number;
  gearShiftSteps: number;
}

export interface SlowPoint {
  dM: number;
  kmh: number;
  gear: number;
  x: number;
  y: number;
}

export interface SafetyCarHistory {
  years: number[];
  races: number;
  withSafetyCar: number;
  withVsc: number;
}

export interface CircuitTelemetry {
  version: 1;
  circuitId: string;
  source: TelemetrySource;
  sectors: { s1Ms: number; s2Ms: number; s3Ms: number; boundariesM: [number, number] };
  speedTraps: { i1Kmh: number | null; i2Kmh: number | null; stKmh: number | null };
  metrics: LapMetrics;
  slowPoints: SlowPoint[];
  safetyCar: SafetyCarHistory | null;
  samples: TelemetrySample[];
}

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isNum(v: unknown): v is number {
  return typeof v === 'number' && Number.isFinite(v);
}

function isStr(v: unknown): v is string {
  return typeof v === 'string';
}

function isNumOrNull(v: unknown): v is number | null {
  return v === null || isNum(v);
}

function isSource(v: unknown): v is TelemetrySource {
  if (!isObject(v)) return false;
  return (
    v.provider === 'OpenF1' &&
    v.license === 'CC BY-NC-SA 4.0' &&
    v.url === 'https://openf1.org' &&
    v.session === 'Qualifying' &&
    isNum(v.year) &&
    isNum(v.round) &&
    isStr(v.raceName) &&
    isNum(v.sessionKey) &&
    isNum(v.meetingKey) &&
    isNum(v.driverNumber) &&
    isStr(v.driverId) &&
    isStr(v.driverCode) &&
    isNum(v.lapNumber) &&
    isStr(v.lapTime) &&
    isNum(v.lapDurationMs) &&
    isStr(v.fetchedAt)
  );
}

function isMetrics(v: unknown): v is LapMetrics {
  if (!isObject(v)) return false;
  return (
    isNum(v.lapLengthM) &&
    isNum(v.topSpeedKmh) &&
    isNum(v.minSpeedKmh) &&
    isNum(v.fullThrottlePct) &&
    isNum(v.brakingPct) &&
    isNum(v.gearShiftSteps)
  );
}

function isSlowPoint(v: unknown): v is SlowPoint {
  return isObject(v) && isNum(v.dM) && isNum(v.kmh) && isNum(v.gear) && isNum(v.x) && isNum(v.y);
}

function isSafetyCar(v: unknown): v is SafetyCarHistory | null {
  if (v === null) return true;
  if (!isObject(v)) return false;
  return (
    Array.isArray(v.years) &&
    v.years.every(isNum) &&
    isNum(v.races) &&
    isNum(v.withSafetyCar) &&
    isNum(v.withVsc)
  );
}

function isSample(v: unknown): v is TelemetrySample {
  return Array.isArray(v) && v.length === 8 && v.every(isNum) && (v[5] === 0 || v[5] === 1);
}

export function isCircuitTelemetry(v: unknown): v is CircuitTelemetry {
  if (!isObject(v)) return false;
  if (v.version !== 1 || !isStr(v.circuitId) || !isSource(v.source)) return false;

  const sectors = v.sectors;
  if (
    !isObject(sectors) ||
    !isNum(sectors.s1Ms) ||
    !isNum(sectors.s2Ms) ||
    !isNum(sectors.s3Ms) ||
    !Array.isArray(sectors.boundariesM) ||
    sectors.boundariesM.length !== 2 ||
    !sectors.boundariesM.every(isNum)
  ) {
    return false;
  }

  const traps = v.speedTraps;
  if (!isObject(traps) || !isNumOrNull(traps.i1Kmh) || !isNumOrNull(traps.i2Kmh) || !isNumOrNull(traps.stKmh)) {
    return false;
  }

  return (
    isMetrics(v.metrics) &&
    Array.isArray(v.slowPoints) &&
    v.slowPoints.every(isSlowPoint) &&
    isSafetyCar(v.safetyCar) &&
    Array.isArray(v.samples) &&
    v.samples.every(isSample)
  );
}
